"""Time-parameterized mocap paths executed through native actions only."""
import json
from pathlib import Path
import numpy as np
import mw_tool


def run(s,p,record=False):
    s.reset()
    obj=s.obs[4:7].copy(); goal=s.target_pos.copy()
    trace=[]
    def step(action):
        s.step(action)
        if record:trace.append(np.r_[s.env.tcp_center,s.obs[4:7],s.data.qvel[-6:],s.data.mocap_pos[0]])
    def line(target,n,profile='linear'):
        start=s.data.mocap_pos[0].copy()
        for i in range(1,n+1):
            alpha=i/n
            if profile=='smooth':alpha=alpha*alpha*(3-2*alpha)
            desired=start+alpha*(target-start)
            a=(desired-s.data.mocap_pos[0])/.01
            step(np.r_[np.clip(a,-1,1),1])
    approach=np.r_[obj[:2]+[p.get('back_x',-.025),p.get('back_y',.060)],p.get('high_z',.14)]
    line(approach,p.get('approach_n',35))
    down=approach.copy(); down[2]=p.get('low_z',.055)
    line(down,p.get('down_n',15))
    end=np.r_[goal[:2]+[p.get('end_x',.02),p.get('end_y',.05)],p.get('end_z',.065)]
    line(end,p.get('push_n',40),p.get('profile','linear'))
    for _ in range(p.get('hold_n',25)):step([0,0,0,1])
    result=dict(params=p,distance=float(np.linalg.norm(s.obs[4:7]-goal)),object=s.obs[4:7].tolist(),tcp=s.env.tcp_center.tolist(),steps=len(s.actions),success=s.check()['success'],speed=float(np.linalg.norm(s.data.qvel[-6:-3])))
    return result,np.asarray(trace)

if __name__=='__main__':
    s=mw_tool.Session()
    results=[]; best=1
    for pn in [30,40,50,65]:
        for y in [.04,.05,.06]:
            for x in [.01,.02,.03]:
                p=dict(push_n=pn,end_x=x,end_y=y)
                r,_=run(s,p)
                results.append(r)
                if r['distance']<best:
                    best=r['distance']
                    print(json.dumps(r),flush=True)
                    s.save_trajectory(path='/app/output/waypoint_best.npz',meta=r)
    Path('/app/output/waypoint_results.json').write_text(json.dumps(results,indent=2))
